 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':390,'height':844});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.add_init_script('if(!localStorage.getItem("vgp-prototype-v1"))localStorage.setItem("vgp-prototype-v1",'+json.dumps(json.dumps(source))+');');page.goto('http://127.0.0.1:8000/prototype-vgp.html#home');page.locator('#settingsToggle').click();page.locator('#namingSettings').click();page.locator('#bulkNamingType').evaluate("e=>{e.value='type';e.dispatchEvent(new Event('change',{bubbles:true}));}");page.locator('#bulkRenameType').click();f=page.locator('#catalogItemForm');f.locator('[name=label]').fill('Marchepied corrigé');page.once('dialog',lambda d:d.dismiss());f.get_by_role('button',name='Enregistrer le libellé').click();assert json.loads(page.evaluate("localStorage.getItem('vgp-prototype-v1')"))==source;page.once('dialog',lambda d:d.accept());f.get_by_role('button',name='Enregistrer le libellé').click();expect(page.locator('#catalogItemDialog')).not_to_be_visible();saved=json.loads(page.evaluate("localStorage.getItem('vgp-prototype-v1')"));assert all(e['designation']=='Marchepied corrigé · M30' for e in saved['equipment']);assert all(e['controls']==old['controls'] and e['months']==old['months'] for e,old in zip(saved['equipment'],source['equipment']));page.locator('#namingDialog [data-close]').click();page.locator('#menuToggle').click();page.locator('#navigation [data-view=material]').click();page.locator('#list tbody tr').first.get_by_role('button',name='Ouvrir',exact=True).click();page.locator('#edit').click();page.locator('#renameEquipmentVariant').click();f.locator('[name=label]').fill('M16');page.once('dialog',lambda d:d.accept());f.get_by_role('button',name='Enregistrer le libellé').click();expect(page.locator('#equipmentForm [name=designation]')).to_have_value('Marchepied corrigé · M16');page.locator('#editFreeEquipmentName').click();name=page.locator('#equipmentForm [name=designation]');expect(name).to_be_editable();name.fill('Nom corrigé individuel');page.locator('#equipmentForm').get_by_role('button',name='Enregistrer l’équipement',exact=True).click();expect(page.locator('#editor')).not_to_be_visible();saved=json.loads(page.evaluate("localStorage.getItem('vgp-prototype-v1')"));assert saved['equipment'][0]['designation']=='Nom corrigé individuel';assert not saved['equipment'][0]['typeId'];assert saved['equipment'][1]['designation']=='Marchepied corrigé · M16';assert saved['equipment'][0]['controls']==source['equipment'][0]['controls'];assert saved['equipment'][0]['originalDesignation']=='Import original 1';page.reload();page.locator('#list tbody tr').filter(has_text='FICTIF-1').get_by_role('button',name='Ouvrir',exact=True).click();expect(page.locator('#detailTitle')).to_contain_text('Nom corrigé individuel');assert not errors,errors;b.close()
